var o=[{title:`Porque importa`,text:`Com a idade, a massa muscular, a força, a potência e o equilíbrio mudam muitas vezes, embora o ritmo varie muito entre pessoas. O treino de resistência pode tornar mais fáceis as tarefas do dia a dia, como levantar-se de uma cadeira, subir escadas e carregar as compras. A atividade aeróbica apoia a saúde cardiovascular e a resistência.`},{title:`Treine várias capacidades`,text:`Uma semana prática mistura treino de força, atividade aeróbica moderada e alguma prática de equilíbrio. As orientações oficiais para adultos com 65 anos ou mais recomendam especificamente pelo menos 150 minutos de atividade aeróbica moderada por semana, fortalecimento muscular em dois dias e trabalho de equilíbrio. Na casa dos cinquenta, siga as orientações gerais de atividade para adultos.`},{title:`Escolha movimentos úteis`,text:`Levantar da cadeira, subidas a um degrau com apoio, remadas, press e caminhadas com carga podem todos ser adaptados ao ponto em que está agora. Alguns adultos mais velhos saudáveis beneficiam de exercícios de potência supervisionados, feitos com controlo e intenção rápida. Isso não significa passar para exercícios arriscados de alto impacto sem se preparar para eles.`},{title:`Progrida com feedback`,text:`Torne os exercícios mais difíceis à medida que a sua competência e a sua força melhoram, mas espere que a recuperação dependa de condições de saúde, do sono e do treino passado. Procure aconselhamento profissional em caso de tonturas novas, sintomas no peito, dor sem explicação ou problemas de equilíbrio. A sua idade não é um diagnóstico e não pode substituir uma avaliação adequada, e por si só não é razão para excluir exercício mais pesado.`}];var s=[{label:`CDC: atividade física em adultos mais velhos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/older-adults.html`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};